<?php
session_start();require_once __DIR__."/config/koneksi.php";
if(!isset($_SESSION['user'])){header("Location:login.php");exit;}
$uid=(int)$_SESSION['user']['id'];
$stmt=$conn->prepare("SELECT a.*, b.bid_amount AS my_bid, b.bid_time FROM auctions a JOIN bids b ON b.auction_id=a.id AND b.user_id=? WHERE b.id=(SELECT b2.id FROM bids b2 WHERE b2.auction_id=a.id AND b2.user_id=? ORDER BY b2.bid_amount DESC,b2.bid_time DESC LIMIT 1) ORDER BY b.bid_time DESC");$stmt->bind_param("ii",$uid,$uid);$stmt->execute();$result=$stmt->get_result();
function rupiah($n){return 'Rp '.number_format((float)$n,0,',','.');}function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');}
?>
