<?php while($r=$result->fetch_assoc()): $winner=(int)$r['winner_user_id']===$uid && $r['winner_status']==='ditentukan'; $payment=null; if($winner){$p=$conn->prepare("SELECT * FROM payments WHERE auction_id=? AND user_id=? ORDER BY id DESC LIMIT 1");$p->bind_param("ii",$r['id'],$uid);$p->execute();$payment=$p->get_result()->fetch_assoc();} ?>
<tr><td><strong><?=e($r['title'])?></strong><br><small class="muted"><?=date('d/m/Y H:i',strtotime($r['bid_time']))?></small></td><td><?=rupiah($r['my_bid'])?></td><td><?=rupiah($r['current_price'])?></td><td><?php if($winner):?><span class="badge green">🏆 Menang</span><?php elseif($r['status']==='aktif'):?><span class="badge green">Aktif</span><?php else:?><span class="badge gray">Selesai</span><?php endif;?></td><td><?php if($winner && (!$payment || $payment['payment_status']!=='paid')):?><a class="btn" href="pembayaran.php?id=<?=$r['id']?>">💳 Bayar</a><?php elseif($winner):?><span class="badge green">Lunas</span><?php else:?><a class="btn" href="detail.php?id=<?=$r['id']?>">Detail</a><?php endif;?></td></tr>
